// Provides analyze(text) and re-exports normalize and tokenize.
// This file is evaluated after normalize.js and tokenizer.js.

// Re-export the peer functions for convenience.
var normalize = typeof normalize !== 'undefined' ? normalize : globalThis.normalize;
var tokenize = typeof tokenize !== 'undefined' ? tokenize : globalThis.tokenize;

function analyze(text) {
    var tokens = tokenize(text);
    var count = tokens.length;
    var unique = [];
    var frequencies = {};
    var seen = {};
    var i;
    for (i = 0; i < count; i++) {
        var token = tokens[i];
        // Handle tokens like "constructor" safely.
        if (!Object.prototype.hasOwnProperty.call(frequencies, token)) {
            frequencies[token] = 0;
        }
        frequencies[token] += 1;
        if (!Object.prototype.hasOwnProperty.call(seen, token)) {
            seen[token] = true;
            unique.push(token);
        }
    }
    var summary = count + ' tokens; ' + unique.length + ' unique';
    return {
        tokens: tokens,
        count: count,
        unique: unique,
        frequencies: frequencies,
        summary: summary
    };
}

// Ensure the functions are available globally (QuickJS top-level scope).
if (typeof globalThis !== 'undefined') {
    globalThis.analyze = analyze;
    globalThis.normalize = normalize;
    globalThis.tokenize = tokenize;
}

// Also expose directly for direct script evaluation if needed.
var pipeline = {
    analyze: analyze,
    normalize: normalize,
    tokenize: tokenize
};

// No console, no I/O, no exports.
// End of pipeline.js
","tokenizer.js":"function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var current = '';
  var i;
  for (i = 0; i < normalized.length; i++) {
    var ch = normalized.charAt(i);
    if (isAsciiAlnum(ch)) {
      current += ch;
    } else if (ch === "'") {
      // Apostrophe is allowed interior only; if we have content before,
      // tentatively include it, but it will be removed if it ends up at edge.
      current += ch;
    } else {
      // separator: flush current after trimming trailing apostrophes
      if (current.length > 0) {
        current = stripEdgeApostrophes(current);
        if (current.length > 0 && current !== "a" && current !== "the") {
          tokens.push(current);
        }
        current = '';
      }
    }
  }
  if (current.length > 0) {
    current = stripEdgeApostrophes(current);
    if (current.length > 0 && current !== "a" && current !== "the") {
      tokens.push(current);
    }
  }
  return tokens;
}

function normalize(text) {
  var s = String(text);
  s = s.normalize('NFKC');
  s = s.normalize('NFD');
  s = s.replace(/[\u0300-\u036f]/g, '');
  s = s.toLowerCase();
  s = s.replace(/\s+/g, ' ');
  s = s.trim();
  return s;
}

function isAsciiAlnum(ch) {
  var code = ch.charCodeAt(0);
  return (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

function stripEdgeApostrophes(str) {
  var start = 0;
  var end = str.length;
  while (start < end && str.charAt(start) === "'") start++;
  while (end > start && str.charAt(end - 1) === "'") end--;
  return str.substring(start, end);
}
